-- Generated by model/lib/sql/generate.mjs. L1's load of FC Horizon IN from cells/FC Horizon IN.csv in the folder of input cells, into its empty table.
-- Two rows for one cell add up.
-- @csv cells/FC Horizon IN.csv
INSERT INTO "FC Horizon IN" SELECT coalesce(k0."Versions", fpabench_error('cells name a member Versions does not have: ' || c."Versions")), coalesce(k1."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), coalesce(k2."Months", fpabench_error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Versions" k0 ON k0.name = c."Versions" LEFT JOIN "dim Years" k1 ON k1.name = c."Years" LEFT JOIN "dim Months" k2 ON k2.name = c."Months"
GROUP BY 1, 2, 3;
ANALYZE "FC Horizon IN";
